import { AppShell, Button, ConsentCheckbox, Field } from "@wizard/ui-kit";
import { useEntityMutation, useState } from "@wizard/sdk";

export default function Main() {
  const [form, setForm] = useState({ name: "", phone: "", consent: false });
  const requests = useEntityMutation("request");
  return (
    <AppShell title={"Онлайн-запись в салон красоты к мастерам"}>
      <p>{"У нас салон красоты в спальном районе: шесть мастеров (маникюр, стрижки, брови), администратор и я как владелица. Клиенты записываются по телефону и в мессенджерах, администратор ведёт тетрадь, бывают накладки. Нужна онлайн-запись: клиент выбирает услугу, мастера и свободное время, видит цену и длительность. У каждого мастера свой график по дням недели, перерывы и выходные; одна запись не может пересекаться с другой у того же мастера. Отменить или перенести запись клиент может не позже чем за 3 часа, дальше — только через администратора. За сутки клиенту приходит напоминание в Telegram или на почту. Администратор видит расписание всех мастеров на день, может записать клиента сам и отметить «пришёл» или «не пришёл». Мастер видит только свои записи. Раз в месяц хочу отчёт: загрузка мастеров, выручка по услугам, доля неявок. Оплата на месте, предоплату не берём. Сейчас график мастеров ведёт старший мастер клиент, переносы она согласует в Telegram клиент."}</p>
      <ul>
        <li>{"Выбор свободного времени"}</li>
        <li>{"Длительность услуги"}</li>
        <li>{"Без пересечений у мастера"}</li>
        <li>{"Отмена не позже чем за 3 часа"}</li>
        <li>{"Напоминание за сутки"}</li>
        <li>{"Отметка неявки"}</li>
        <li>{"Отчёт по загрузке и выручке"}</li>
      </ul>
      <p>{"Запись не пересекается с другой у того же мастера"}</p>
      <p>{"Клиент не может отменить позже чем за 3 часа"}</p>
      <p>{"Мастер видит только свои записи"}</p>
      <p>{"Администратор может отметить неявку"}</p>
      <form onSubmit={(e) => { e.preventDefault(); void requests.create({ contact_name: form.name, contact_phone: form.phone }, { consent: true }); }}>
        <Field name="contact_name" label="Имя" type="string" value={form.name} onChange={(v) => setForm({ ...form, name: String(v) })} />
        <Field name="contact_phone" label="Телефон" type="phone" value={form.phone} onChange={(v) => setForm({ ...form, phone: String(v) })} />
        <ConsentCheckbox checked={form.consent} onChange={(v) => setForm({ ...form, consent: v })} />
        <Button type="submit">{"Отправить заявку"}</Button>
      </form>
    </AppShell>
  );
}
